mg_require_method('GET');$pdo=mg_db();$slug=strtolower(trim((string)($_GET['slug']??'')));if($slug===''||preg_match('/^[a-z0-9][a-z0-9-]{0,119}$/',$slug)!==1)mg_fail('Invalid profile.',422);
try{$profile=$pdo->prepare('SELECT id,user_id FROM public_profiles WHERE slug=? LIMIT 1');$profile->execute([$slug]);$row=$profile->fetch(PDO::FETCH_ASSOC);if(!$row)mg_fail('Profile not found.',404);if(!mg_rcs_table_exists($pdo,'customer_review_replies'))mg_ok(['reviews'=>[],'schema_ready'=>false]);$stmt=$pdo->prepare("SELECT r.public_id,r.featured_on_profile,r.featured_in_case_study,rr.public_id reply_id,rr.reply_body,rr.created_at,rr.updated_at FROM customer_reviews r LEFT JOIN customer_review_replies rr ON rr.review_id=r.id AND rr.status='published' WHERE r.merchant_user_id=? AND r.status='published' ORDER BY r.submitted_at DESC,r.id DESC LIMIT 50");$stmt->execute([(int)$row['user_id']]);$items=array_map(static fn(array $r):array=>['id'=>(string)$r['public_id'],'featured_on_profile'=>!empty($r['featured_on_profile']),'featured_in_case_study'=>!empty($r['featured_in_case_study']),'reply'=>!empty($r['reply_id'])?['id'=>(string)$r['reply_id'],'body'=>(string)$r['reply_body'],'created_at'=>(string)$r['created_at'],'updated_at'=>(string)$r['updated_at']]:null],$stmt->fetchAll(PDO::FETCH_ASSOC));mg_ok(['reviews'=>$items,'schema_ready'=>true]);}catch(Throwable $e){mg_fail('Unable to load review replies.',500);}
